 "content": "def transform(grid):
    """Overlay the two binary panels; mark cells present in both with 2."""
    h, w = len(grid), len(grid[0])
    # Panels are separated by a full row or column of a non-background color.
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != 0:
            top, bottom = grid[:r], grid[r + 1:]
            if len(top) == len(bottom) and top:
                return [[2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
                        for ra, rb in zip(top, bottom)]
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1 and col[0] != 0:
            left, right = [row[:c] for row in grid], [row[c + 1:] for row in grid]
            if left and len(left[0]) == len(right[0]) and left[0]:
                return [[2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
                        for ra, rb in zip(left, right)]
    raise ValueError("No centered full separator dividing two equal panels")
